        /// Minimum height of a text field on iOS (dsField). Off the control ladder; a candidate to move to control (36) or hit (44) in the call-site sweep.
        static let fieldHeight: CGFloat = 40
        /// Round icon button: add-tag toggle, play badge over a cover.
        static let iconButton: CGFloat = 32
        /// Diameter of the toggle thumb.
        static let switchThumb: CGFloat = 24
        /// Cover thumbnail in dense lists (info panel).
        static let coverXs: CGFloat = 32
        /// Cover thumbnail in the playback queue.
        static let coverSm: CGFloat = 40
        /// Cover thumbnail in a library row and the transport bar. 60 and 66 in macOS code fold into it.
        static let coverMd: CGFloat = 64
        /// Cover preview in the song form.
        static let coverLg: CGFloat = 96
        /// Status LED dot.
        static let dotSm: CGFloat = 8
        /// Chart legend dot.
        static let dotMd: CGFloat = 10
        /// Cover in a Library song row (iOS). Scales with Dynamic Type up to 1.5x. cover-md (64) stays for the transport bar and the web row.
        static let coverRow: CGFloat = 56
        /// Minimum width and height of the count badge on a selected filter chip (capsule; number in caption semibold).
        static let badge: CGFloat = 20
        /// Width of the trailing fade on the Library chip row while more chips exist beyond the screen edge; removed when scrolled to the end.
        static let chipFade: CGFloat = 24
        /// Detent fraction (of screen height) of filter sheets that have a search field (Tags, Genres, Countries), so the sheet does not change height when the keyboard opens. A fraction, not a length.
        static let sheetTall: CGFloat = 0.8
        /// Cover on Song Details (between cover-lg 96 and full width). Swift name: DS.Component.detailsCover.
        static let detailsCover: CGFloat = 200
    }

    // MARK: Opacity
    enum Opacity {
        /// A Library row with no audio anywhere ("No audio yet"): the cover and the text are drawn at this opacity; the row stays tappable. Swift name: DS.Opacity.dim.
        static let dim: CGFloat = 0.55
    }

}

extension SwiftUI.Color {
    /// A colour with separate light and dark values, resolved by the system appearance.
    init(light: (Double, Double, Double, Double), dark: (Double, Double, Double, Double)) {
#if canImport(UIKit)
        self.init(uiColor: UIColor { trait in
            let c = trait.userInterfaceStyle == .dark ? dark : light
            return UIColor(red: c.0, green: c.1, blue: c.2, alpha: c.3)
        })
#else
        self.init(nsColor: NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
            let c = isDark ? dark : light
            return NSColor(srgbRed: c.0, green: c.1, blue: c.2, alpha: c.3)
        })
#endif
    }
}

/// One SwiftUI shadow level. `tintOpacity` is the alpha to apply when a call site supplies its own colour (see dsShadow in DSModifiers.swift).
struct DSShadow {
    let color: SwiftUI.Color
    let tintOpacity: Double
    let radius: CGFloat
    let x: CGFloat
    let y: CGFloat
}

/// A cubic-bezier easing curve (the x1 y1 x2 y2 of CSS cubic-bezier).
struct DSBezier {
    let x1: Double, y1: Double, x2: Double, y2: Double
    init(_ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double) { self.x1 = x1; self.y1 = y1; self.x2 = x2; self.y2 = y2 }
}
